          "catalogBody": "只有在确认 API 条款后，才允许使用完全对应的别名或改名；当前查询使用官方标题。实质性不匹配和占位记录会被暂缓发布。纽约市行政法规记录仅供参考，因为它们不属于州参议院 API，也没有存储来源文本。",
          "reviewTitle": "API 核验不等于律师批准",
          "reviewBody": "API 核验确认来源身份、返回的文本、日期和内容哈希。这并不表示律师已经批准构成要件、主观心理状态、罪名等级、刑罚或现行性解释。这些法律字段在律师审查前仍标记为“待律师审查”。",
