          "description": "就业记录、绩效评估、志愿者参与、社区联系、奖项和品格证明，对你的案件和长期声誉都很重要。现在是开始收集它们的好时机。来自了解你的人的品格证明信，对法官和雇主都可能产生真实的影响。",
