    "caseData": {
      "title": "我们如何处理案件路线图和AI工具数据",
      "summary": "案件路线图、AI聊天、文件摘要工具和紧急情况分诊步骤均仅使用临时服务器内存。这些工具的数据不会写入持久数据库。以下是详细说明：",
      "memoryOnly": {
        "title": "存储什么，不存储什么",
        "description": "输入可能包括司法辖区、指控、案件阶段、羁押状态、关注点、自由文本、上传文件文字和生成的指导。这些记录保存在服务器内存中，而非永久案件数据库。请勿输入姓名、联系方式、案件编号或其他不必要的敏感信息。"
      },
      "piiRedaction": {
        "title": "额外保障：AI 处理前自动遮盖",
        "description": "AI 处理前，我们会尝试遮盖电话、电子邮件和社会安全号码等常见身份信息。自动遮盖可能遗漏敏感内容，因此这是一项保障而非保证。AI 输入由 Anthropic 处理。"
      },
      "autoDelete": {
        "title": "24小时内存到期",
        "description": "案件和反馈记录通常在24小时内从内存过期，服务重启可能更早清除。指导可能在内存中缓存约15分钟。部分同意、审计、安全和运营元数据可能保留到重启，或保留在提供商日志中。"
      },
      "serverRestart": {
        "title": "完全不存储数据的工具",
        "description": "以下几种工具完全不发出任何服务器请求：记录清除资格评估工具、附带后果筛查工具和公设辩护人入档清单。这三种工具均完全在您的浏览器中运行；律师工具在您的设备本地生成可下载的 .docx 文件，不会向我们的服务器传输任何数据。减轻情节备忘录生成器的核心表单及其 .docx 导出功能也以同样方式运行，但它还提供一项可选的“AI 润色”步骤，该步骤确实会将您输入的字段发送到我们的服务器进行一次性 AI 处理（详见下方“外部数据来源”）。网站上所有其他静态页面（权利指南、支持资源、法庭日期指南、移民指南）同样不收集数据。"
      }
    },
