        "dont3": "案件相关对话若在律师-客户特权之外进行，则不受保护。朋友和家人可能被法律要求出庭作证，证明您对他们说过的话。您的律师可以指导您，如果有的话，分享什么是合适的。",
        "dont4": "在案件待决期间发生新的刑事事件，可能影响保释条件、增加法律风险并使辩护复杂化。",
        "supportBridge": "被捕影响的不只是法律案件。住房、福利、就业和家庭稳定往往同时受到影响——法院命令可能还要求您完成特定课程或社区服务。本网站的生活支持部分涵盖了所有这些内容。",
        "supportBridgeLink": "前往生活支持",
        "twoOneBridge": "如需获取附近的本地服务，请拨打或发短信至211——免费，全天候提供服务。",
        "c1Title": "法庭日期",
        "c1": "法庭日期是强制性的。缺席听证将导致逮捕令和没收任何保释金。为每个预定日期设置多个提醒。",
        "c2Title": "保释条件",
        "c2": "保释条件必须严格遵守。任何违反——包括意外违反——都会导致立即重新被捕。",
        "c3Title": "对话",
        "c3": "在律师-客户特权之外讨论案件不受保护。监狱电话、短信、与家人朋友的对话以及社交媒体帖子都可以被获取并用作证据。",
        "c4Title": "证人联系",
        "c4": "在活跃案件期间与指控受害者或证人联系可能引发法律问题，包括妨碍司法。律师应在任何此类接触之前给予建议。",
        "c5Title": "您的记忆",
        "c5": "您对所发生事件的记忆对您的辩护可能很重要。趁记忆犹新记录下来，便于日后与律师分享。"
