    "aiDisclosure": {
      "title": "人工智能技术披露",
      "p1": "明确标注为 AI 辅助的功能使用 Anthropic Claude Sonnet 4.6，包括案件路线图与聊天指导、减轻情节叙述润色、信函生成、文件摘要与问答，以及律师文件生成与摘要。",
      "p2": "案件路线图包含规则模式，并可在 AI 不可用时使用该模式。规则模式不会向 Anthropic 发送路线图输入。大多数其他 AI 辅助功能在 Anthropic 不可用时会显示错误。",
      "p3": "静态权利、支持、筛查和资源页面不会在请求时用 AI 生成文字。其内容来自公共法律来源以及精选或有时经过综合的数据集，仍可能不完整、属于估算、已过时、翻译有误或不正确。",
      "p4": "案件和反馈记录保存在服务器内存中，而非永久数据库，通常在24小时内或服务重启时清除。指导可能缓存约15分钟。部分同意、审计、安全和运营元数据可能保留到重启，或保留在提供商日志中。",
      "p5": "AI 生成文字不能替代持牌律师建议，也无法针对每项事实定制。AI 可能遗漏信息、出错或给出过时引证。请向律师和最新官方来源核实重要细节、截止日期和引证。",
      "p6_pre": "AI 处理前，我们会尝试遮盖姓名、电话、地址和社会安全号码等常见身份信息。自动遮盖可能遗漏敏感内容，请勿提交不必要的个人信息。完整详情请参阅",
      "p6_post": "。"
    },
    "screeningTools": {
      "title": "筛查与资格评估工具",
      "p1": "犯罪记录清除资格筛查工具是一个决策树——不使用 AI，也不进行服务器调用。它完全在您的浏览器中运行。不传输或存储任何数据。",
      "p2": "附带后果筛查工具是一个是/否问卷，根据您的回答标识生活领域风险（住房、就业、移民、监护权等）。不使用 AI，也不进行服务器调用。一切在您的浏览器中运行——没有数据离开您的设备。",
      "p3": "公设辩护人入案清单是供律师和倡导者使用的电子入案表格。它完全在您的浏览器中运行，不进行服务器调用，并在您的设备本地生成可下载的 .docx 文件。不向我们的服务器传输或存储任何数据。",
      "p4": "减轻情节备忘录生成器的核心表单和本地 .docx 导出在浏览器中运行。可选 AI 润色会通过我们的服务器将已填写字段发送至 Anthropic Claude。OpenDefender 不会将请求写入永久备忘录数据库，但会进行标准运营处理，Anthropic 可能按标准条款保留 API 数据最多30天。",
      "p5": "案底错误识别指南和 FCRA 权利信息仅供参考。它们描述一般流程和权利。请直接向相关机构——联邦调查局、您所在州的刑事记录库或背景调查公司——核实所有争议程序和截止日期。"
    },
    "publicApi": {
      "title": "公共 API",
      "intro": "OpenDefender 在 /api/v1/ 提供免费的只读公共 API，允许第三方开发者和法律援助组织将我们的法律参考数据——指控、法规、转处计划和术语表——嵌入到他们自己的工具和网站中。",
      "item1": "所有 API 端点均为只读——不通过 API 提交或收集用户数据",
      "item2": "AI 驱动的指导不通过公共 API 提供——需要直接使用本网站",
      "item3": "通过 API 返回的数据是一般性法律参考信息——不是法律建议，也不建立律师-当事人关系",
      "item4": "嵌入我们数据或组件的第三方有责任在其自己的应用程序中包含适当的免责声明",
      "item5": "适用速率限制（每个 IP 每分钟 60 次请求）以确保公平访问",
      "footer": "适用于本网站的\"仅供一般信息参考\"限制同样适用于通过 API 访问的任何数据。OpenDefender 对第三方如何呈现或使用通过公共 API 获取的数据不承担责任。"
    },
