      "title": "关于本项目",
      "p1": "OpenDefender 是一个免费的开源资源，面向在美国刑事司法和移民系统中寻求帮助的人，以及应对这些系统所带来的实际生活困扰的人。它提供一般性权利信息、早期倡导指导，以及涵盖住房、就业、财务、家庭、心理健康、移民和犯罪记录清除的实用支持资源。这不是法律服务，也不提供法律建议。",
