          "title": "合法逮捕时的搜查",
          "description": "当警员进行有效逮捕时，他们可以搜查被捕者本人及其周围可及范围内的区域，以寻找武器或证据。",
          "limit": "这不延伸至整个住宅或车辆。仅限于被捕者本人及其伸手可及的范围。"
